package com.hotelmanagement.hms.payment.dto; import com.hotelmanagement.hms.payment.model.*; import java.math.*; import java.util.*; public record PaymentResponse(UUID id,UUID folioId,PaymentMethod method,String currency,BigDecimal originalAmount,BigDecimal fxRate,BigDecimal baseAmount,PaymentStatus status,UUID paymentAccountId,String paymentAccountName,String paymentAccountIdentifier){public static PaymentResponse from(Payment p){return new PaymentResponse(p.getId(),p.getFolioId(),p.getMethod(),p.getCurrency(),p.getOriginalAmount(),p.getFxRate(),p.getBaseAmount(),p.getStatus(),p.getPaymentAccountId(),p.getPaymentAccountName(),com.hotelmanagement.hms.payment.service.PaymentAccountMasking.mask(p.getPaymentAccountIdentifier()));}}
